<?php
require_once __DIR__ . '/helpers.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Método no permitido.'],405);
require_csrf();$d=body_json();$action=clean_string($d['accion']??'');$email=strtolower(clean_string($d['correo']??''));if(!validate_email($email))json_response(['error'=>'Ingresa un correo válido.'],422);$pdo=db();$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');
if($action==='solicitar'){
 $key=hash('sha256','reset|'.$email.'|'.$ip);$rate=$pdo->prepare('SELECT intentos,ventana_inicio,bloqueado_hasta FROM login_intentos WHERE clave=?');$rate->execute([$key]);$rr=$rate->fetch();if($rr&&!empty($rr['bloqueado_hasta'])&&strtotime($rr['bloqueado_hasta'])>time())json_response(['error'=>'Has solicitado varios códigos. Espera 15 minutos.'],429);
 if(!$rr||strtotime($rr['ventana_inicio'])<time()-900)$pdo->prepare('INSERT INTO login_intentos(clave,intentos,ventana_inicio,bloqueado_hasta) VALUES(?,1,NOW(),NULL) ON DUPLICATE KEY UPDATE intentos=1,ventana_inicio=NOW(),bloqueado_hasta=NULL')->execute([$key]);else{$n=(int)$rr['intentos']+1;$pdo->prepare('UPDATE login_intentos SET intentos=?,bloqueado_hasta=IF(? >= 4,DATE_ADD(NOW(),INTERVAL 15 MINUTE),NULL) WHERE clave=?')->execute([$n,$n,$key]);}
 $st=$pdo->prepare("SELECT id FROM usuarios WHERE correo=? AND rol='alumno' AND estado='activo' LIMIT 1");$st->execute([$email]);$uid=(int)($st->fetchColumn()?:0);
 if(!$uid)json_response(['ok'=>true,'mensaje'=>'Si existe una cuenta activa con ese correo, se generó una solicitud de recuperación. Para esta versión local el proceso se simula en pantalla.']);
 $code=(string)random_int(100000,999999);$pdo->prepare('UPDATE password_reset_tokens SET usado_en=NOW() WHERE usuario_id=? AND usado_en IS NULL')->execute([$uid]);$pdo->prepare('INSERT INTO password_reset_tokens(usuario_id,token_hash,intentos,expira_en) VALUES(?,?,0,DATE_ADD(NOW(),INTERVAL 15 MINUTE))')->execute([$uid,hash('sha256',$code)]);
 $response=['ok'=>true,'mensaje'=>'Código de recuperación simulado generado. Tiene una vigencia de 15 minutos.'];if(defined('APP_ENV')&&APP_ENV==='development')$response['codigo_demo']=$code;json_response($response);
}
if($action==='restablecer'){$code=clean_string($d['codigo']??'');$password=(string)($d['password_nueva']??'');if(!preg_match('/^\d{6}$/',$code)||strlen($password)<8||preg_match('/\s/',$password))json_response(['error'=>'Código inválido o contraseña menor a 8 caracteres.'],422);
 $st=$pdo->prepare("SELECT t.id,t.usuario_id,t.token_hash,t.intentos FROM password_reset_tokens t JOIN usuarios u ON u.id=t.usuario_id WHERE u.correo=? AND u.rol='alumno' AND t.usado_en IS NULL AND t.expira_en>NOW() ORDER BY t.id DESC LIMIT 1");$st->execute([$email]);$row=$st->fetch();if(!$row)json_response(['error'=>'El código no es válido o expiró. Solicita uno nuevo.'],422);
 if(!hash_equals($row['token_hash'],hash('sha256',$code))){$attempts=(int)$row['intentos']+1;$pdo->prepare('UPDATE password_reset_tokens SET intentos=?,usado_en=IF(? >= 5,NOW(),usado_en) WHERE id=?')->execute([$attempts,$attempts,$row['id']]);json_response(['error'=>$attempts>=5?'Se agotaron los intentos. Solicita un código nuevo.':'El código no es válido.'],422);}
 $pdo->beginTransaction();try{$pdo->prepare('UPDATE usuarios SET password_hash=?,actualizado_en=NOW() WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$row['usuario_id']]);$pdo->prepare('UPDATE password_reset_tokens SET usado_en=NOW() WHERE id=?')->execute([$row['id']]);$pdo->commit();json_response(['ok'=>true,'mensaje'=>'Contraseña actualizada. Ya puedes iniciar sesión.']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[Upskill reset] '.$e->getMessage());json_response(['error'=>'No fue posible actualizar la contraseña.'],500);}}
json_response(['error'=>'Acción no válida.'],422);
